SELECT COUNT(*)
FROM meeting_participants
WHERE meeting_id = #{meetingId}
    AND user_id = #{userId}
    AND participant_status = 'ACTIVE'

SELECT COUNT(*)
FROM meeting_participants
WHERE participant_id = #{participantId}
  AND meeting_id = #{meetingId}
  AND participant_status = 'ACTIVE'

SELECT participant_id AS participantId, meeting_id AS meetingId, user_id AS userId, participant_status AS participantStatus, input_status AS inputStatus
FROM meeting_participants
WHERE meeting_id = #{meetingId} AND user_id = #{userId}
